import numpy as np
from .base import BaseLayer


class ReLU(BaseLayer):
    def __init__(self):
        pass

    def forward(self, x: np.ndarray) -> np.ndarray:
        # x: input array of any shape, dtype float64
        # Returns: output of same shape, dtype float64
        # Formula: max(0, x)
        return np.maximum(0, x).astype(np.float64)


class LeakyReLU(BaseLayer):
    def __init__(self, negative_slope: float = 0.01):
        self.negative_slope = negative_slope

    def forward(self, x: np.ndarray) -> np.ndarray:
        # x: input array of any shape, dtype float64
        # Returns: output of same shape, dtype float64
        # Formula: x if x > 0 else negative_slope * x
        result = np.where(x > 0, x, self.negative_slope * x)
        return result.astype(np.float64)


class Sigmoid(BaseLayer):
    def __init__(self):
        pass

    def forward(self, x: np.ndarray) -> np.ndarray:
        # x: input array of any shape, dtype float64
        # Returns: output of same shape, dtype float64
        # Formula: 1 / (1 + exp(-x))
        # Must be numerically stable
        # Numerically stable sigmoid implementation:
        # if x >= 0: 1 / (1 + exp(-x))
        # if x < 0: exp(x) / (1 + exp(x))
        # Or using: 1 / (1 + exp(-np.clip(x, -500, 500))) for safety
        # But let me implement the standard stable version:
        result = np.where(x >= 0, 
                         1 / (1 + np.exp(-x)),
                         np.exp(x) / (1 + np.exp(x)))
        return result.astype(np.float64)
