import numpy as np
from .base import BaseLayer
from .padding import get_output_shape


class MaxPool2D(BaseLayer):
    def __init__(self, kernel_size: int, stride: int = None):
        self.kernel_size = kernel_size
        if stride is None:
            self.stride = kernel_size
        else:
            self.stride = stride

    def forward(self, x: np.ndarray) -> np.ndarray:
        # x: input of shape (batch_size, height, width, channels)
        batch_size = x.shape[0]
        height = x.shape[1]
        width = x.shape[2]
        channels = x.shape[3]

        # Calculate output dimensions using get_output_shape with padding=0, dilation=1
        out_height, out_width = get_output_shape((height, width), self.kernel_size, self.stride, padding=0, dilation=1)

        # Output shape: (batch_size, out_height, out_width, channels)
        output = np.zeros((batch_size, out_height, out_width, channels), dtype=np.float64)

        for b in range(batch_size):
            for h_out in range(out_height):
                for w_out in range(out_width):
                    h_start = h_out * self.stride
                    h_end = h_start + self.kernel_size
                    w_start = w_out * self.stride
                    w_end = w_start + self.kernel_size

                    for c in range(channels):
                        region = x[b, h_start:h_end, w_start:w_end, c]  # (kernel_size, kernel_size)
                        output[b, h_out, w_out, c] = np.max(region)

        return output


class AvgPool2D(BaseLayer):
    def __init__(self, kernel_size: int, stride: int = None):
        self.kernel_size = kernel_size
        if stride is None:
            self.stride = kernel_size
        else:
            self.stride = stride

    def forward(self, x: np.ndarray) -> np.ndarray:
        batch_size = x.shape[0]
        height = x.shape[1]
        width = x.shape[2]
        channels = x.shape[3]

        out_height, out_width = get_output_shape((height, width), self.kernel_size, self.stride, padding=0, dilation=1)

        output = np.zeros((batch_size, out_height, out_width, channels), dtype=np.float64)

        for b in range(batch_size):
            for h_out in range(out_height):
                for w_out in range(out_width):
                    h_start = h_out * self.stride
                    h_end = h_start + self.kernel_size
                    w_start = w_out * self.stride
                    w_end = w_start + self.kernel_size

                    for c in range(channels):
                        region = x[b, h_start:h_end, w_start:w_end, c]  # (kernel_size, kernel_size)
                        output[b, h_out, w_out, c] = np.mean(region)

        return output
